 const check=()=>{if(now()>=deadline)throw TIMEOUT;};
 const rank=a=>a.type==='Place'?(a.at===4?0:1):2;
 function actions(s,ply){
  const a=legalActions(s);
  return (s.toMove==='X'&&ply>4?a.filter(x=>x.type==='Place'):a).sort((a,b)=>rank(a)-rank(b));
