import {createController} from './controller.mjs';
import {createHUD} from './hud.mjs';
import {createBoard} from './board.mjs';
export function mountGame(root){
 root.innerHTML='<h1>Hearth &amp; Thread</h1><div data-hud></div><div data-board></div><p data-score></p><p data-live role="status" aria-live="polite"></p>';
 const hudRoot=root.querySelector('[data-hud]'),boardRoot=root.querySelector('[data-board]');
 const live=root.querySelector('[data-live]'),score=root.querySelector('[data-score]');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 let game,pending=null,lastRefill='';
 let best=0;try{best=Number(localStorage.getItem('hearth-best'))||0;}catch{}
 function cancelAI(){
  if(!pending)return;const j=pending;pending=null;
  clearTimeout(j.timer);j.worker.terminate();j.reject(new Error('cancelled'));
 }
 function requestAI(payload){
  cancelAI();
  return new Promise((resolve,reject)=>{
   const worker=new Worker(new URL('./ai.worker.mjs',import.meta.url),{type:'module'});
   const job={worker,reject,timer:null};pending=job;
   function finish(error,reply){
    if(pending!==job)return;pending=null;clearTimeout(job.timer);worker.terminate();
    if(error)reject(error);else resolve(reply);
   }
   worker.onmessage=e=>finish(null,e.data);worker.onerror=()=>finish(new Error('worker failed'));
   job.timer=setTimeout(()=>finish(new Error('worker watchdog')),600);
   worker.postMessage(payload);
  });
 }
 const board=createBoard(boardRoot,{onCommit:a=>game.commit(a),onSkipWon:()=>game.skipWon(),announce:t=>live.textContent=t});
 const hud=createHUD(hudRoot,{onDraft:(t,r)=>game.draft(t,r),onAgain:()=>game.newRun(),onPower:t=>board.selectPower(t)});
 function render(s){
  hud(s);board.render(s);
  if(s.phase==='won')hudRoot.querySelector('.turn-status').textContent='A golden seam! Continue when ready.';
  score.textContent=`Score: ${s.score} · Best: ${best}`;
  const refill=s.events.find(e=>e.type==='heartsRefill');
  const eventKey=`${s.revision}:${s.level}`;
  if(refill&&lastRefill!==eventKey){
   lastRefill=eventKey;
   const hearts=hudRoot.querySelector('.attempts>span');hearts.replaceChildren();
   for(let i=0;i<3;i++){
    const heart=document.createElement('span');heart.textContent='♥';heart.style.display='inline-block';hearts.append(heart);
    if(i>=refill.from&&!reduced)heart.animate([{transform:'scale(.5)',opacity:.25},{transform:'scale(1.2)',opacity:1},{transform:'scale(1)',opacity:1}],{duration:300,delay:(i-refill.from)*120,fill:'backwards'});
   }
   live.textContent='New room: three board attempts ready.';
  }
 }
 game=createController({render,requestAI,cancelAI,reducedMotion:reduced,onOutcome:s=>{
  best=Math.max(best,s.score);try{localStorage.setItem('hearth-best',String(best));}catch{}
  score.textContent=`Score: ${s.score} · Best: ${best}`;
 }});
 return {game,destroy(){cancelAI();root.replaceChildren();}};
}

