import {initial,canApply,applyAction} from './rules.mjs';
import {tacticalFallback} from './ai.worker.mjs';
const TYPES=['shatter','slide','ward'];
export function createController({render,requestAI,cancelAI=()=>{},onOutcome=()=>{},later=setTimeout,reducedMotion=false}){
 let revision=0,inFlight=null,s;
 const snapshot=()=>structuredClone(s),publish=()=>render(snapshot());
 function stopAI(){if(inFlight!==null)cancelAI();inFlight=null;}
 function wait(ms,fn){const r=revision,phase=s.phase;later(()=>{if(r===revision&&s.phase===phase)fn();},reducedMotion?0:ms);}
 function end(phase){s.phase=phase;publish();onOutcome(snapshot());}
 function newRun(){
  stopAI();revision++;
  s={revision,phase:'draft',level:1,drawsThisLevel:0,secondWindAvailable:true,heat:0,score:0,
   inventory:{shatter:0,slide:0,ward:0},position:null,events:[],starterDraft:true,lossReason:null};publish();
 }
 function freshBoard(){
  stopAI();revision++;s.revision=revision;
  const cells=Array(9).fill(null);
  if(s.level===2)cells[0]='rock';if(s.level===3){cells[0]='X';cells[8]='O';}
  s.position=initial(cells,s.level===4?'O':'X',s.inventory,s.level===5?1:0);
  s.heat=0;s.events=[];s.lossReason=null;
  s.phase=s.position.toMove==='X'?'player':'ai';publish();kickAI();
 }
 function draft(type,replace=null){
  if(s.phase!=='draft')return false;
  if(type===null){if(s.starterDraft)return false;}
  else {
   if(!TYPES.includes(type))return false;
   const total=Object.values(s.inventory).reduce((a,b)=>a+b,0);
   if(total>=3){if(!TYPES.includes(replace)||s.inventory[replace]<1)return false;s.inventory[replace]--;}
   s.inventory[type]++;
  }
  s.starterDraft=false;freshBoard();return true;
 }
 function lose(reason){
  s.phase='lost';s.lossReason=reason;publish();
  wait(1000,()=>{
   if(reason==='line'&&s.secondWindAvailable){s.secondWindAvailable=false;freshBoard();}
   else end('defeat');
  });
 }
 function settle(){
  const result=s.position.result;
  if(result==='X'){
   if(s.level===5){end('victory');return;}
   const from=3-s.drawsThisLevel;
   s.level++;s.drawsThisLevel=0;s.phase='draft';s.events=[{type:'heartsRefill',from,to:3}];publish();return;
  }
  if(result==='draw'){
   s.drawsThisLevel++;
   if(s.drawsThisLevel>=3){lose('boards');return;}
   freshBoard();return;
  }
  s.phase=s.position.toMove==='X'?'player':'ai';publish();kickAI();
 }
 function skipWon(){if(s.phase!=='won')return false;settle();return true;}
 function commit(action,actor='X'){
  if((actor==='X'&&s.phase!=='player')||(actor==='O'&&s.phase!=='ai'))return false;
  if(s.position.toMove!==actor)return false;
  const r=applyAction(s.position,action);if(r.error)return false;
  revision++;s.revision=revision;s.position=r.position;s.inventory={...r.position.powersX};s.events=r.events;
  s.heat=Math.min(10,s.heat+r.events.filter(e=>e.type==='placement').length+(r.position.result==='X'?2:0));
  if(r.position.result==='O')lose('line');
  else if(r.position.result==='X'){
   s.score+=100+50*(3-s.drawsThisLevel)+(r.events.some(e=>e.type==='power')?25:0);
   s.phase='won';publish();wait(700,settle);
  }else{s.phase='transition';publish();wait(300,settle);}
  return true;
 }
 function kickAI(){
  if(s.phase!=='ai'||inFlight!==null)return;
  const r=revision;inFlight=r;
  const payload={revision:r,position:structuredClone(s.position),level:s.level,drawsThisLevel:s.drawsThisLevel};
  function receive(reply){
   if(inFlight!==r||revision!==r||s.phase!=='ai')return;
   inFlight=null;
   const a=reply?.revision===r&&canApply(s.position,reply.action)?reply.action:tacticalFallback(s.position);
   if(a)commit(a,'O');
  }
  try{Promise.resolve(requestAI(payload)).then(receive,()=>receive(null));}catch{receive(null);}
 }
 function preview(action){return s.phase==='player'?applyAction(s.position,action):{error:'INPUT_LOCKED'};}
 newRun();
 return {newRun,draft,preview,skipWon,commit:action=>commit(action,'X'),getState:snapshot};
}

