 if(has('slide'))for(let from=0;from<9;from++)if(c[from]===p){
  for(let to=0;to<9;to++)if(free(c,to)){
   const b=[...c];b[from]=null;b[to]=p;
   for(let at=0;at<9;at++)if(free(b,at))out.push({type:'Slide',from,to,at});
